#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float cell_size;   // 4..32 px
    float contrast;    // 0..2
    float gamma;       // 0.1..3.0
    float invert;      // 0/1
    float charset;     // 0=blocks,1=dots,2=lines
};

struct VIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VOut { float4 pos [[position]]; float2 uv; };

vertex VOut main0(VIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float luma(float3 c){ return dot(c, float3(0.2126,0.7152,0.0722)); }

fragment float4 fragment_main(VOut in [[stage_in]], texture2d<float> src [[texture(0)]], constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 pix = in.uv * u.OutputSize.xy;
    float cs = clamp(u.cell_size, 4.0, 32.0);
    float2 cell = floor(pix / cs);
    float2 cellUV = (cell + 0.5) * cs / u.OutputSize.xy; // sample at cell center

    float3 c = src.sample(s, cellUV).rgb;
    float L = pow(clamp(luma(c), 0.0, 1.0), max(0.1, u.gamma));
    L = saturate((L - 0.5) * max(0.0, u.contrast) + 0.5);
    if (u.invert > 0.5) L = 1.0 - L;

    // Draw a procedural glyph within the cell based on L and mode
    float2 f = fract(pix / cs); // local coords within cell [0,1)
    float v = 0.0;
    if (u.charset < 0.5) {
        // blocks: map to coarse block density 0..1
        // 0 (space), 0.25, 0.5, 0.75, 1.0
        float d = floor(L * 4.0 + 0.5) / 4.0;
        v = step(f.x, d) * step(f.y, 1.0); // vertical fill
        // Use both axes for richer blocks
        v = max(v, step(f.y, d));
    } else if (u.charset < 1.5) {
        // dots: halftone circle size
        float2 uv = (f - 0.5);
        float r = length(uv) * 1.4142;
        float rad = mix(0.05, 0.5, 1.0 - L);
        v = 1.0 - smoothstep(rad-0.01, rad+0.01, r);
    } else {
        // lines: number of lines increases as L decreases
        float lines = mix(2.0, 10.0, 1.0 - L);
        float stripe = fract(f.y * lines);
        v = step(stripe, 0.5);
    }

    // Composite glyph over a desaturated base
    float3 base = mix(float3(L), c, 0.2);
    float3 outc = mix(base * 0.1, float3(1.0), v);

    return float4(saturate(outc), 1.0);
}

